# WARNING: DO NOT EDIT THIS FILE DIRECTLY.
# This file is a child copy that shadows or shares code with the Tools repository.
# Canonical changes must be made in the Tools repository under src/shared/python/
# and synchronized back to UpstreamDrift. Direct edits here risk being lost.

"""Pytest configuration for sidekick tests."""

from pathlib import Path
import sys


def _repo_root(start: Path) -> Path:
    """Return the repository root for this copied test tree."""
    for parent in start.resolve().parents:
        if (parent / "pyproject.toml").is_file() and (
            parent / "src" / "shared" / "python"
        ).is_dir():
            return parent
    raise RuntimeError(f"Could not locate repository root from {start}")


ROOT = _repo_root(Path(__file__))
SHARED_PYTHON = ROOT / "src" / "shared" / "python"
if not SHARED_PYTHON.is_dir():
    raise RuntimeError(f"Shared Python package path is missing: {SHARED_PYTHON}")

for path in (ROOT, SHARED_PYTHON):
    path_text = str(path)
    if path_text not in sys.path:
        sys.path.insert(0, path_text)
